function total(h: number, j: number): number {
  return h * j;
}
console.log(total(5000));

function pesan(menu: string, jumlah = 1): string {
  return `${jumlah}x ${menu}`;
}
console.log(pesan("Teh", 2));

function jumlah(...n: number[]): number {
  return n.reduce((a, x) => a + x, 0);
}
console.log(jumlah());

function ubah(a: number[], f: (n: number) => number) {
  return a.map(f);
}
console.log(ubah([1], () => "a"));

function stop(p: string): never {
  throw new Error(p);
}
